#include "partial_CRC.h"
//=============================================
// Partial CRC
//=============================================
void partial_crc_HW_T4(int* dec_d, int* lfsr, int column_number, int ShortenedBit, int* idxTermination)
{
    int i;
    // iteration당 column마다 호출되는 함수 — heap 할당 3쌍 대신 고정 크기 지역 배열 (CRC_LEN/DEC_D_LEN은 컴파일 타임 상수, 스택 ~1.4KB)
    int tmp1[CRC_LEN];
    int tmp2[CRC_LEN];
    int tmp_dec_d[DEC_D_LEN];
    int TP1 = idxTermination[0];
    int TP2 = idxTermination[1];
    int TP3 = idxTermination[2];
    int TP4 = idxTermination[3];
    for (i = 0; i < DEC_D_LEN; i++) {
        tmp_dec_d[i] = 0;
    }
    //division 1
    if (column_number == TP4) {
        if (ShortenedBit == 0) {
            for (i = 0; i < DEC_D_LEN; i++)
                tmp_dec_d[DEC_D_LEN - 1 - i] = dec_d[i];
        }
    }
    else {
        for (i = 0; i < DEC_D_LEN; i++)
            tmp_dec_d[DEC_D_LEN - 1 - i] = dec_d[i];
    }
    division_DEX(tmp_dec_d, tmp1);   // argv:[UNCERTAIN]
    // division 2
    if (column_number == TP4) {
        if (ShortenedBit == 0)
            division_REX_Last_Col_Shortened_00Byte(lfsr, tmp2);
    }
    else {
        division_REX(lfsr, tmp2);
    }
    // XOR
    for (i = 0; i < CRC_LEN; i++) {
        lfsr[i] = tmp1[i] ^ tmp2[i];
    }
    // XOR order down
    /*
    // order 1
    if (column_number == TP1) {
        if (ShortenedBit == 0)  division_TP1_Shortened_00Byte(lfsr, tmp1);
        for (i = 0; i < CRC_LEN; i++) {
            lfsr[i] = tmp1[i];
        }
    }
    // order 2
    if (column_number == TP2) {
        if (ShortenedBit == 0)  division_TP2_Shortened_00Byte(lfsr, tmp1);
        for (i = 0; i < CRC_LEN; i++) {
            lfsr[i] = tmp1[i];
        }
    }
    // order 3
    if (column_number == TP3) {
        if (ShortenedBit == 0)  division_TP3_Shortened_00Byte(lfsr, tmp1);
        for (i = 0; i < CRC_LEN; i++) {
            lfsr[i] = tmp1[i];
        }
    }
    */
}
